package com.fintech.banking.controller;

import com.fintech.banking.dto.WireTemplateDto;
import com.fintech.banking.entity.WireTransferTemplate;
import com.fintech.banking.repository.WireTransferTemplateRepository;
import com.fintech.banking.security.UserAccountPrincipal;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/banking/wire-templates")
public class WireTransferController {

    private final WireTransferTemplateRepository templateRepository;

    public WireTransferController(WireTransferTemplateRepository templateRepository) {
        this.templateRepository = templateRepository;
    }

    @GetMapping("/{templateId}")
    public ResponseEntity<WireTemplateDto> getWireTemplate(
            @PathVariable Long templateId,
            @AuthenticationPrincipal UserAccountPrincipal principal) {
        WireTransferTemplate template = templateRepository
                .findByIdAndCorporateAccountId(templateId, principal.getCorporateAccountId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Template not found or access denied"));
        WireTemplateDto dto = new WireTemplateDto(
                template.getId(),
                template.getBeneficiaryName(),
                template.getIban(),
                template.getSwiftBic(),
                template.getDailyDisbursementLimit()
        );
        return ResponseEntity.ok(dto);
    }
}
